1	// Package rollup downsamples a time series into fixed windows aligned to
2	// the Unix epoch, and merges rollups that share a window size.
3	//
4	// A Roller is safe for concurrent use: samples may be filed, windows read,
5	// and rollers merged from multiple goroutines at once. Every read observes
6	// an internally consistent snapshot, and a merge or batch is visible to
7	// other callers either in full or not at all.
8	package rollup
9	
10	import (
11		"errors"
12		"math"
13		"math/bits"
14		"sort"
15		"sync"
16		"sync/atomic"
17		"time"
18	)
19	
20	// ErrOutOfOrder is returned by Add when a sample predates the most recent
21	// sample the roller has already accepted.
22	var ErrOutOfOrder = errors.New("rollup: out of order")
23	
24	// ErrWindowMismatch is returned by Merge when the two rollers use different
25	// window sizes.
26	var ErrWindowMismatch = errors.New("rollup: window mismatch")
27	
28	// Sample is one record in a batch passed to AddBatch: a value observed at
29	// one instant.
30	type Sample struct {
31		At    time.Time
32		Value float64
33	}
34	
35	// Window holds the aggregate statistics of the samples filed into one
36	// window. Start is the window's left-closed, right-open lower bound.
37	type Window struct {
38		Start time.Time
39		Count int64
40		Sum   float64
41		Min   float64
42		Max   float64
43	}
44	
45	// Roller aggregates samples into fixed windows of a single size.
46	//
47	// The zero value is not usable; build one with New. All methods are safe
48	// to call concurrently from multiple goroutines.
49	type Roller struct {
50		// mu guards buckets, back, latest, and hasAny. window and id are
51		// fixed at construction and read without the lock.
52		//
53		// buckets is one flat slice kept sorted by window start: samples
54		// arrive in non-decreasing time order, so Add appends in amortized
55		// constant time, Windows reads out without re-sorting, and Merge is
56		// a single linear pass over both sides.
57		//
58		// back holds backfilled windows keyed by window start: a sample that
59		// lands before the newest window opens its bucket here, so a new
60		// window costs one map insert instead of shifting a sorted tail and a
61		// mass backfill stays linear. Once the number of backfilled windows
62		// catches up with buckets, they are sorted once and folded into it,
63		// amortizing that sort over the inserts. Every read consults both
64		// buckets and back, and no window start appears in both at the same
65		// time.
66		mu      sync.RWMutex
67		id      uint64
68		window  time.Duration
69		buckets []Window
70		back    map[time.Time]Window
71		latest  time.Time
72		hasAny  bool
73	}
74	
75	// idGen hands out unique roller IDs so Merge can lock two rollers in a
76	// consistent order and concurrent cross-merges cannot deadlock.
77	var idGen atomic.Uint64
78	
79	// New builds a roller with the given window size. It panics with
80	// "rollup: bad window" if window is not positive.
81	func New(window time.Duration) *Roller {
82		if window <= 0 {
83			panic("rollup: bad window")
84		}
85		return &Roller{
86			id:     idGen.Add(1),
87			window: window,
88		}
89	}
90	
91	// startOf returns the start of the window containing at, aligned to an
92	// integer multiple of the window size since the Unix epoch.
93	func (r *Roller) startOf(at time.Time) time.Time {
94		return alignStart(at, r.window.Nanoseconds())
95	}
96	
97	// alignStart returns the start of the window of width w nanoseconds
98	// containing at, aligned to an integer multiple of w since the Unix epoch.
99	// The arithmetic is exact for any time value, including ones whose
100	// nanosecond offset from the epoch does not fit in an int64.
101	func alignStart(at time.Time, w int64) time.Time {
102		sec := at.Unix()
103		nsec := int64(at.Nanosecond())
104		if sec >= -9223372036 && sec <= 9223372035 {
105			// sec*1e9+nsec fits in an int64. Rounding a negative ns down to
106			// a window multiple can reach ns-(w-1), so stay on the fast
107			// path only when that product cannot overflow either.
108			if ns := sec*1e9 + nsec; ns >= math.MinInt64+w-1 {
109				start := ns / w
110				if ns%w != 0 && ns < 0 {
111					start--
112				}
113				return time.Unix(0, start*w).UTC()
114			}
115		}
116		return windowStartWide(sec, nsec, w)
117	}
118	
119	// windowStartWide is the 128-bit slow path of alignStart, for times whose
120	// nanosecond offset from the epoch overflows an int64.
121	func windowStartWide(sec, nsec, w int64) time.Time {
122		// t = sec*1e9 + nsec as a 128-bit two's-complement value (hi, lo).
123		uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
124		if sec < 0 {
125			uhi -= 1e9
126		}
127		hi := int64(uhi)
128		lo := ulo + uint64(nsec)
129		if lo < ulo {
130			hi++
131		}
132		// Round t down to a multiple of w: start = t - floorMod(t, w).
133		rem := floorMod128(hi, lo, w)
134		if lo < rem {
135			hi--
136		}
137		lo -= rem
138		// Split start into whole seconds and nanoseconds.
139		ns := floorMod128(hi, lo, 1e9)
140		if lo < ns {
141			hi--
142		}
143		lo -= ns
144		return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
145	}
146	
147	// floorMod128 returns t mod y for the signed 128-bit value t = (hi<<64)|lo
148	// and positive y, with the result in [0, y).
149	func floorMod128(hi int64, lo uint64, y int64) uint64 {
150		yu := uint64(y)
151		if hi >= 0 {
152			return rem128(uint64(hi), lo, yu)
153		}
154		// Negate the 128-bit value, take the remainder, and reflect it back
155		// into [0, y) for floored (not truncated) division.
156		mlo := -lo
157		mhi := -uint64(hi)
158		if lo != 0 {
159			mhi--
160		}
161		if r := rem128(mhi, mlo, yu); r != 0 {
162			return yu - r
163		}
164		return 0
165	}
166	
167	// quo128 returns (hi<<64|lo)/y for a signed 128-bit dividend known to be an
168	// exact multiple of y, with a quotient that fits in an int64.
169	func quo128(hi int64, lo uint64, y int64) int64 {
170		yu := uint64(y)
171		if hi >= 0 {
172			q, _ := bits.Div64(uint64(hi), lo, yu)
173			return int64(q)
174		}
175		mlo := -lo
176		mhi := -uint64(hi)
177		if lo != 0 {
178			mhi--
179		}
180		q, _ := bits.Div64(mhi, mlo, yu)
181		return -int64(q)
182	}
183	
184	// rem128 returns (hi<<64 | lo) mod y for unsigned hi, lo and y > 0.
185	func rem128(hi, lo, y uint64) uint64 {
186		if hi >= y {
187			hi %= y
188		}
189		return bits.Rem64(hi, lo, y)
190	}
191	
192	// windowIndex locates the window starting at start in ws, which must be
193	// sorted by window start. The second result reports whether it exists;
194	// when it does not, the index is where it would be inserted to keep ws
195	// sorted, i.e. the first window whose start is not before start.
196	func windowIndex(ws []Window, start time.Time) (int, bool) {
197		sec, nsec := start.Unix(), int64(start.Nanosecond())
198		lo, hi := 0, len(ws)
199		for lo < hi {
200			mid := int(uint(lo+hi) >> 1)
201			s := ws[mid].Start
202			if ss, sn := s.Unix(), int64(s.Nanosecond()); ss < sec || (ss == sec && sn < nsec) {
203				lo = mid + 1
204			} else {
205				hi = mid
206			}
207		}
208		if lo < len(ws) {
209			if s := ws[lo].Start; s.Unix() == sec && int64(s.Nanosecond()) == nsec {
210				return lo, true
211			}
212		}
213		return lo, false
214	}
215	
216	// addTo folds one sample into w. Count saturates at math.MaxInt64 instead
217	// of overflowing; Sum, Min, and Max keep updating afterwards.
218	func addTo(w *Window, value float64) {
219		if w.Count < math.MaxInt64 {
220			w.Count++
221		}
222		w.Sum += value
223		if value < w.Min {
224			w.Min = value
225		}
226		if value > w.Max {
227			w.Max = value
228		}
229	}
230	
231	// Add files a sample into its window. A sample earlier than the most recent
232	// accepted sample is rejected with ErrOutOfOrder and leaves the roller
233	// unchanged; a sample at the same instant is accepted and counted again.
234	//
235	// Concurrent Adds are serialized: each takes effect in the order it
236	// acquires the roller, and the out-of-order check is measured against the
237	// samples accepted before it in that order.
238	func (r *Roller) Add(at time.Time, value float64) error {
239		r.mu.Lock()
240		defer r.mu.Unlock()
241		if r.hasAny && at.Before(r.latest) {
242			return ErrOutOfOrder
243		}
244		r.fileLocked(at, value)
245		r.latest = at
246		r.hasAny = true
247		return nil
248	}
249	
250	// AddBatch files a batch of samples as one atomic unit: either every
251	// sample takes effect or none does. The samples may arrive in any order
252	// and are not checked against each other; several samples at the same
253	// instant are each counted. Each sample is filed into its epoch-aligned
254	// window exactly as Add would file it.
255	//
256	// If any sample predates the most recent sample the roller has already
257	// accepted, the whole batch is rejected with ErrOutOfOrder and the roller
258	// is left unchanged. Otherwise the most-recent marker advances to the
259	// later of its previous value and the newest sample in the batch. A nil
260	// or empty batch is accepted, changes nothing, and does not advance the
261	// marker.
262	//
263	// The batch is atomic with respect to every other call on the roller:
264	// concurrent adds, batches, merges, range reads, and cursor creation
265	// observe the roller wholly before or wholly after the batch.
266	func (r *Roller) AddBatch(samples []Sample) error {
267		if len(samples) == 0 {
268			return nil
269		}
270		r.mu.Lock()
271		defer r.mu.Unlock()
272		// One pass to validate the batch against the accepted marker and find
273		// its newest instant; nothing is filed until every sample is known to
274		// be acceptable, so a rejection leaves the roller untouched.
275		latest := samples[0].At
276		for _, s := range samples {
277			if r.hasAny && s.At.Before(r.latest) {
278				return ErrOutOfOrder
279			}
280			if s.At.After(latest) {
281				latest = s.At
282			}
283		}
284		for _, s := range samples {
285			r.fileLocked(s.At, s.Value)
286		}
287		if r.hasAny && r.latest.After(latest) {
288			latest = r.latest
289		}
290		r.latest = latest
291		r.hasAny = true
292		return nil
293	}
294	
295	// fileLocked folds one sample into its window. The caller must hold mu
296	// and must already have cleared the out-of-order check.
297	func (r *Roller) fileLocked(at time.Time, value float64) {
298		start := r.startOf(at)
299		n := len(r.buckets)
300		switch {
301		case n == 0:
302			r.buckets = append(r.buckets, newBucket(start, value))
303		case !start.Before(r.buckets[n-1].Start):
304			// The common case: the sample lands in the newest window or
305			// just past it, so the sorted order is maintained for free.
306			if r.buckets[n-1].Start.Equal(start) {
307				addTo(&r.buckets[n-1], value)
308			} else {
309				r.buckets = append(r.buckets, newBucket(start, value))
310			}
311		default:
312			// The sample belongs to an older window, which can only happen
313			// after a merge brought in windows past latest. A window that
314			// already exists is updated in place; a new one goes into the
315			// backfill map, so inserting it never shifts the sorted tail of
316			// buckets and the cost of a mass backfill stays linear in the
317			// number of windows accepted.
318			if i, ok := windowIndex(r.buckets, start); ok {
319				addTo(&r.buckets[i], value)
320			} else if w, ok := r.back[start]; ok {
321				addTo(&w, value)
322				r.back[start] = w
323			} else {
324				if r.back == nil {
325					r.back = make(map[time.Time]Window)
326				}
327				r.back[start] = newBucket(start, value)
328				r.maybeFlushBack()
329			}
330		}
331	}
332	
333	// newBucket returns a window holding a single sample.
334	func newBucket(start time.Time, value float64) Window {
335		return Window{Start: start, Count: 1, Sum: value, Min: value, Max: value}
336	}
337	
338	// maybeFlushBack folds the backfilled windows into buckets once they
339	// number at least half as many as buckets, so the sorting and merge cost
340	// amortizes to constant time per backfilled window. The caller must hold
341	// mu.
342	func (r *Roller) maybeFlushBack() {
343		if len(r.back)*2 < len(r.buckets) {
344			return
345		}
346		r.buckets = mergeWindows(r.buckets, r.sortedBackLocked())
347		r.back = nil
348	}
349	
350	// sortedBackLocked returns the backfilled windows in time order. The
351	// caller must hold mu; the returned slice is a fresh snapshot.
352	func (r *Roller) sortedBackLocked() []Window {
353		back := make([]Window, 0, len(r.back))
354		for _, w := range r.back {
355			back = append(back, w)
356		}
357		sort.Slice(back, func(i, j int) bool {
358			return back[i].Start.Before(back[j].Start)
359		})
360		return back
361	}
362	
363	// mergeWindows returns the sorted union of two window slices, each sorted
364	// by window start, combining the statistics of windows that share a
365	// start: counts and sums add, minimums take the smaller, maximums take
366	// the larger. The result is always a fresh slice.
367	func mergeWindows(a, b []Window) []Window {
368		merged := make([]Window, 0, len(a)+len(b))
369		i, j := 0, 0
370		for i < len(a) && j < len(b) {
371			switch {
372			case a[i].Start.Before(b[j].Start):
373				merged = append(merged, a[i])
374				i++
375			case b[j].Start.Before(a[i].Start):
376				merged = append(merged, b[j])
377				j++
378			default:
379				w := a[i]
380				w.Count = satAdd(w.Count, b[j].Count)
381				w.Sum += b[j].Sum
382				if b[j].Min < w.Min {
383					w.Min = b[j].Min
384				}
385				if b[j].Max > w.Max {
386					w.Max = b[j].Max
387				}
388				merged = append(merged, w)
389				i++
390				j++
391			}
392		}
393		merged = append(merged, a[i:]...)
394		merged = append(merged, b[j:]...)
395		return merged
396	}
397	
398	// Window returns the bucket whose start matches start exactly. The second
399	// result is false when no bucket starts at that instant; no nearby bucket
400	// is substituted. The returned Window is a copy and stays valid no matter
401	// what is filed afterwards.
402	func (r *Roller) Window(start time.Time) (Window, bool) {
403		r.mu.RLock()
404		defer r.mu.RUnlock()
405		if i, ok := windowIndex(r.buckets, start); ok {
406			return r.buckets[i], true
407		}
408		if w, ok := r.back[start.UTC()]; ok {
409			return w, true
410		}
411		return Window{}, false
412	}
413	
414	// Windows returns all buckets in time order. An empty roller yields an
415	// empty slice. The result is a snapshot of one moment: samples filed after
416	// the call do not alter it.
417	func (r *Roller) Windows() []Window {
418		r.mu.RLock()
419		defer r.mu.RUnlock()
420		if len(r.back) != 0 {
421			return mergeWindows(r.buckets, r.sortedBackLocked())
422		}
423		out := make([]Window, len(r.buckets))
424		copy(out, r.buckets)
425		return out
426	}
427	
428	// Range returns the buckets that overlap the half-open interval
429	// [from, to), in time order. The endpoints are attributed to windows by
430	// the same epoch-aligned, left-closed rule Add uses: the first bucket
431	// returned is the one containing from, and a bucket starting exactly at
432	// to is excluded. An interval whose end does not come after its start
433	// yields an empty slice, as does an interval no bucket overlaps. The
434	// result is a snapshot of one moment: samples filed after the call do
435	// not alter it.
436	func (r *Roller) Range(from, to time.Time) []Window {
437		r.mu.RLock()
438		defer r.mu.RUnlock()
439		out := []Window{}
440		if !from.Before(to) {
441			return out
442		}
443		back := []Window(nil)
444		if len(r.back) != 0 {
445			back = r.sortedBackLocked()
446		}
447		lo := r.startOf(from)
448		i, _ := windowIndex(r.buckets, lo)
449		j, _ := windowIndex(back, lo)
450		for {
451			var w Window
452			switch {
453			case i < len(r.buckets) && (j >= len(back) || r.buckets[i].Start.Before(back[j].Start)):
454				w = r.buckets[i]
455				i++
456			case j < len(back):
457				w = back[j]
458				j++
459			default:
460				return out
461			}
462			if !w.Start.Before(to) {
463				return out
464			}
465			out = append(out, w)
466		}
467	}
468	
469	// Cursor reads a fixed range of windows in batches. The windows are
470	// snapshot when the cursor is created: samples filed, backfilled, or
471	// merged in afterwards do not alter what the cursor returns, so batched
472	// iteration over a large range never tears, skips, or repeats a window,
473	// and the end of the range is reached deterministically no matter what
474	// is written while the cursor advances.
475	//
476	// A Cursor is safe to advance from multiple goroutines at once; each
477	// batch is handed out exactly once.
478	type Cursor struct {
479		// mu guards pos. windows is fixed at creation and read without the
480		// lock.
481		mu      sync.Mutex
482		windows []Window
483		pos     int
484	}
485	
486	// Cursor returns a cursor over the buckets overlapping the half-open
487	// interval [from, to), selected by the same rule as Range.
488	func (r *Roller) Cursor(from, to time.Time) *Cursor {
489		return &Cursor{windows: r.Range(from, to)}
490	}
491	
492	// Next returns the next batch of up to n windows, in time order. Batches
493	// are consecutive and non-overlapping: together they cover exactly the
494	// windows in the cursor's range. Once the range is exhausted, Next
495	// returns an empty slice and the cursor does not move. A non-positive n
496	// yields an empty slice and does not advance the cursor.
497	func (c *Cursor) Next(n int) []Window {
498		c.mu.Lock()
499		defer c.mu.Unlock()
500		rest := len(c.windows) - c.pos
501		if n <= 0 || rest == 0 {
502			return []Window{}
503		}
504		if n > rest {
505			n = rest
506		}
507		out := make([]Window, n)
508		copy(out, c.windows[c.pos:c.pos+n])
509		c.pos += n
510		return out
511	}
512	
513	// Merge folds other's buckets into this roller: counts and sums add,
514	// minimums take the smaller, maximums take the larger, and buckets only one
515	// side has are carried over as-is. Merging does not affect out-of-order
516	// tracking. It panics with "rollup: nil roller" if other is nil, and
517	// returns ErrWindowMismatch, leaving this roller unchanged, if the window
518	// sizes differ.
519	//
520	// The merge is atomic with respect to every other call on either roller:
521	// concurrent readers see this roller wholly before or wholly after the
522	// merge, and a sample filed into other while the merge runs is either
523	// folded in completely or not at all. If the two rollers merge each other
524	// at the same time, the outcome matches some serial order of the two
525	// merges; neither is lost.
526	func (r *Roller) Merge(other *Roller) error {
527		if other == nil {
528			panic("rollup: nil roller")
529		}
530		if other.window != r.window {
531			return ErrWindowMismatch
532		}
533		if r == other {
534			r.mu.Lock()
535			defer r.mu.Unlock()
536			if len(r.back) != 0 {
537				r.buckets = mergeWindows(r.buckets, r.sortedBackLocked())
538				r.back = nil
539			}
540			for i := range r.buckets {
541				w := &r.buckets[i]
542				w.Count = satAdd(w.Count, w.Count)
543				w.Sum += w.Sum
544			}
545			return nil
546		}
547		// Lock both rollers in ID order so simultaneous merges in
548		// opposite directions cannot deadlock.
549		first, second := r, other
550		if other.id < r.id {
551			first, second = other, r
552		}
553		first.mu.Lock()
554		second.mu.Lock()
555		defer second.mu.Unlock()
556		defer first.mu.Unlock()
557	
558		switch {
559		case len(other.buckets) == 0 && len(other.back) == 0:
560			return nil
561		case len(r.buckets) == 0 && len(r.back) == 0:
562			r.buckets = mergeWindows(other.buckets, other.sortedBackLocked())
563			return nil
564		}
565		left, right := r.buckets, other.buckets
566		if len(r.back) != 0 {
567			left = mergeWindows(r.buckets, r.sortedBackLocked())
568		}
569		if len(other.back) != 0 {
570			right = mergeWindows(other.buckets, other.sortedBackLocked())
571		}
572		// Both sides are sorted by window start, so the merge is one linear
573		// pass and one backing array, no per-bucket copies or lookups.
574		r.buckets = mergeWindows(left, right)
575		r.back = nil
576		return nil
577	}
578	
579	// satAdd returns a + b saturated at math.MaxInt64 instead of overflowing.
580	func satAdd(a, b int64) int64 {
581		if b > math.MaxInt64-a {
582			return math.MaxInt64
583		}
584		return a + b
585	}
