226	// TestRollupIsPureRead checks that deriving a view leaves the roller's
227	// statistics and out-of-order marker untouched, that a mismatched merge
228	// still fails exactly as before, and that out-of-order submission still
229	// returns the existing error value.
230	func TestRollupIsPureRead(t *testing.T) {
231		r := New(time.Minute)
232		if err := r.Add(time.Unix(60, 0), 1); err != nil {
233			t.Fatal(err)
234		}
235		before := r.Windows()
236		_ = r.Rollup(4)
237		_ = r.Rollup(7)
238		after := r.Windows()
239		if len(after) != len(before) || after[0] != before[0] {
240			t.Fatalf("rollup mutated roller stats: %v -> %v", before, after)
241		}
242		// The most-recent marker did not move: a stale sample is still rejected
243		// and the boundary instant is still accepted.
244		if err := r.Add(time.Unix(59, 0), 1); !errors.Is(err, ErrOutOfOrder) {
245			t.Fatalf("want ErrOutOfOrder after rollup, got %v", err)
246		}
247		if err := r.Add(time.Unix(60, 0), 2); err != nil {
248			t.Fatal(err)
249		}
250		// Merging a different window size keeps returning the existing error.
251		if err := r.Merge(New(time.Hour)); !errors.Is(err, ErrWindowMismatch) {
252			t.Fatalf("want ErrWindowMismatch, got %v", err)
253		}
254		// Merge does not enter ordering: after merging in later windows, an
255		// older sample can still be backfilled.
256		ahead := New(time.Minute)
257		if err := ahead.Add(time.Unix(600, 0), 9); err != nil {
258			t.Fatal(err)
259		}
260		if err := r.Merge(ahead); err != nil {
261			t.Fatal(err)
262		}
263		_ = r.Rollup(3)
264		if err := r.Add(time.Unix(120, 0), 5); err != nil {
265			t.Fatalf("backfill after merge+rollup: %v", err)
266		}
267	}
268	
269	// TestRollupEmptyRoller checks every read entry on a view of an empty
270	// roller.
271	func TestRollupEmptyRoller(t *testing.T) {
272		v := New(time.Second).Rollup(4)
273		if w := v.Window(time.Unix(0, 0)); w != (Window{}) {
274			t.Fatalf("empty view window: %+v", w)
