282	}
283	
284	// TestRollupCountSaturates checks that counts merged from covered fine
285	// windows saturate at the int64 ceiling, by the same rule as merging.
286	func TestRollupCountSaturates(t *testing.T) {
287		r := New(time.Minute)
288		r.buckets = append(r.buckets,
289			Window{Start: time.Unix(0, 0).UTC(), Count: math.MaxInt64 - 2, Sum: 1, Min: -2, Max: 1},
290			Window{Start: time.Unix(60, 0).UTC(), Count: 10, Sum: 4, Min: -7, Max: 6},
291		)
292		v := r.Rollup(2)
293		w := v.Window(time.Unix(0, 0))
294		if w.Count != math.MaxInt64 {
295			t.Fatalf("count overflowed: %d", w.Count)
296		}
297		if w.Sum != 5 || w.Min != -7 || w.Max != 6 {
298			t.Fatalf("coarse stats: %+v", w)
299		}
300	}
