302	// TestRollupMinWindowSize checks derivation from the smallest allowed
303	// window: coarse starts stay epoch aligned at nanosecond granularity.
304	func TestRollupMinWindowSize(t *testing.T) {
305		r := New(1) // 1-nanosecond windows
306		for _, ns := range []int64{0, 1, 2, 5} {
307			if err := r.Add(time.Unix(0, ns), float64(ns)); err != nil {
308				t.Fatal(err)
309			}
310		}
311		v := r.Rollup(3) // coarse windows [0,3) and [3,6) nanoseconds
312		w := v.Window(time.Unix(0, 0))
313		if w.Count != 3 || w.Sum != 3 || w.Min != 0 || w.Max != 2 {
314			t.Fatalf("coarse [0,3) ns: %+v", w)
315		}
316		w = v.Window(time.Unix(0, 3))
317		if w.Count != 1 || w.Sum != 5 {
318			t.Fatalf("coarse [3,6) ns: %+v", w)
319		}
