464					// stream: the merge races the other writers, and from
465					// then on new round windows arrive through the backfill
466					// map instead of the append path.
467					if s == 0 && round&511 == 0 {
468						other := New(time.Second)
469						if err := other.Add(time.Unix(int64(1<<30+round), 0), 1); err != nil {
470							t.Errorf("other Add: %v", err)
471						} else if err := r.Merge(other); err != nil {
472							t.Errorf("Merge: %v", err)
473						} else {
474							mergedWindows.Add(1)
475						}
476					}
477					roundDone.Done()
478				}
479			}(s)
480		}
481		for round := 0; round < rounds; round++ {
482			roundDone.Add(shards)
483			close(starts[round])
484			roundDone.Wait()
485		}
486		writers.Wait()
487		close(stop)
488		readers.Wait()
489	
490		got := r.Windows()
491		var total int64
492		for _, w := range got {
493			total += w.Count
494		}
495		if want := accepted.Load() + mergedWindows.Load(); total != want {
496			t.Fatalf("total count %d, want %d accepted plus %d merged",
497				total, accepted.Load(), mergedWindows.Load())
498		}
499		for i := 1; i < len(got); i++ {
500			if !got[i-1].Start.Before(got[i].Start) {
501				t.Fatalf("final windows out of order at %d: %v then %v",
502					i, got[i-1].Start, got[i].Start)
503			}
504		}
505	}
506	
507	// TestMergesAtomicUnderConcurrentReads extends the basic atomicity test
508	// with ranged and cursor reads while merges land in a tight loop: each
509	// visible window set must be one of the serial states, never a partial one.
510	func TestMergesAtomicUnderConcurrentReads(t *testing.T) {
