1	package main
2	
3	import (
4		"bytes"
5		"math"
6		"os"
7		"path/filepath"
8		"strconv"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// runResult captures one invocation of the command against a file on disk.
15	type runResult struct {
16		code   int
17		stdout string
18		stderr string
19	}
20	
21	func runWithFile(t *testing.T, content string, args ...string) runResult {
22		t.Helper()
23		dir := t.TempDir()
24		path := filepath.Join(dir, "samples.txt")
25		if content != "" {
26			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
27				t.Fatal(err)
28			}
29		} else {
30			// An explicitly empty file is different from a missing path.
31			if err := os.WriteFile(path, nil, 0o600); err != nil {
32				t.Fatal(err)
33			}
34		}
35		full := append([]string{"--file", path}, args...)
36		var stdout, stderr bytes.Buffer
37		code := run(full, &stdout, &stderr)
38		return runResult{code, stdout.String(), stderr.String()}
39	}
40	
41	func runArgs(t *testing.T, args ...string) runResult {
42		t.Helper()
43		var stdout, stderr bytes.Buffer
44		code := run(args, &stdout, &stderr)
45		return runResult{code, stdout.String(), stderr.String()}
46	}
47	
48	func TestRunAggregatesWindows(t *testing.T) {
49		content := strings.Join([]string{
50			"0 1",
51			"500000000 2",   // same 1s window
52			"1000000000 -3", // next window
53			"   ",           // whitespace-only, skipped
54			"",              // blank, skipped
55			"1500000000 -0", // negative zero
56			"2000000000 1.5",
57		}, "\n") + "\n"
58		got := runWithFile(t, content, "--window", "1s", "windows")
59		if got.code != 0 {
60			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
61		}
62		want := strings.Join([]string{
63			"0 2 3 1 2",
64			"1000000000 2 -3 -3 -0",
65			"2000000000 1 1.5 1.5 1.5",
66			"",
67		}, "\n")
68		if got.stdout != want {
69			t.Fatalf("stdout = %q, want %q", got.stdout, want)
70		}
71	}
72	
73	func TestRunShortestFloatFormatting(t *testing.T) {
74		// 1e20 renders "1e+20" under 'g' -1; the sum keeps whatever the
75		// floating-point addition yields, still in its shortest form.
76		content := "0 1e20\n0 150000\n"
77		got := runWithFile(t, content, "--window", "1m", "windows")
78		if got.code != 0 {
79			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
80		}
81		if want := "0 2 1.0000000000000015e+20 150000 1e+20\n"; got.stdout != want {
82			t.Fatalf("stdout = %q, want %q", got.stdout, want)
83		}
84	}
85	
86	func TestRunNegativeWindowStart(t *testing.T) {
87		// -1.5s aligns down to -2s in a 2s window; -1s stays in [-2s, 0).
88		content := "-1500000000 4\n-1000000000 8\n"
89		got := runWithFile(t, content, "--window", "2s", "windows")
90		if got.code != 0 {
91			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
92		}
93		if got.stdout != "-2000000000 2 12 4 8\n" {
94			t.Fatalf("stdout = %q", got.stdout)
95		}
96	}
97	
98	func TestRunExtremeTimestamp(t *testing.T) {
99		// MinInt64 aligned to a 3ns window starts at -9223372036854775809,
100		// which is outside the int64 range; the start must print exactly.
101		content := "-9223372036854775808 1\n"
102		got := runWithFile(t, content, "--window", "3ns", "windows")
103		if got.code != 0 {
104			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
105		}
106		if !strings.HasPrefix(got.stdout, "-9223372036854775809 ") {
107			t.Fatalf("stdout = %q", got.stdout)
108		}
109	}
110	
111	func TestRunMaxTimestamp(t *testing.T) {
112		content := "9223372036854775807 1\n"
113		got := runWithFile(t, content, "--window", "1ns", "windows")
114		if got.code != 0 {
115			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
116		}
117		if got.stdout != "9223372036854775807 1 1 1 1\n" {
118			t.Fatalf("stdout = %q", got.stdout)
119		}
120	}
121	
122	func TestRunFlagsBeforeAndAfterSubcommand(t *testing.T) {
123		content := "0 1\n"
124		got := runWithFile(t, content, "windows", "--window=1s")
125		if got.code != 0 {
126			t.Fatalf("flags after subcommand: code = %d, stderr = %q", got.code, got.stderr)
127		}
128		if got.stdout != "0 1 1 1 1\n" {
129			t.Fatalf("stdout = %q", got.stdout)
130		}
131	}
132	
133	func TestRunArgumentErrors(t *testing.T) {
134		cases := []struct {
135			name string
136			args []string
137		}{
138			{"no args", nil},
139			{"missing subcommand", []string{"--file", "x", "--window", "1s"}},
140			{"unknown subcommand", []string{"--file", "x", "--window", "1s", "rollup"}},
141			{"second positional", []string{"--file", "x", "--window", "1s", "windows", "extra"}},
142			{"unknown flag", []string{"--file", "x", "--window", "1s", "windows", "--factor", "2"}},
143			{"missing file", []string{"--window", "1s", "windows"}},
144			{"missing window", []string{"--file", "x", "windows"}},
145			{"empty file value", []string{"--file=", "--window", "1s", "windows"}},
146			{"dangling value", []string{"--file", "x", "--window", "windows"}},
147		}
148		for _, tc := range cases {
149			t.Run(tc.name, func(t *testing.T) {
150				// These cases are all rejected while arguments are parsed,
151				// before any file on disk is consulted.
152				got := runArgs(t, tc.args...)
153				if got.code != 2 {
154					t.Fatalf("code = %d, want 2; stderr = %q", got.code, got.stderr)
155				}
156				if !strings.HasPrefix(got.stderr, "rollupctl: ") {
157					t.Fatalf("stderr = %q, want rollupctl: prefix", got.stderr)
158				}
159				if strings.Count(strings.TrimRight(got.stderr, "\n"), "\n") != 0 {
160					t.Fatalf("stderr must be one line, got %q", got.stderr)
161				}
162				if got.stdout != "" {
163					t.Fatalf("stdout must be empty, got %q", got.stdout)
164				}
165			})
166		}
167	}
168	
169	func TestRunBadWindowDuration(t *testing.T) {
170		for _, value := range []string{"0s", "-1ns", "5", "not-a-duration", "1.5"} {
171			t.Run(value, func(t *testing.T) {
172				got := runWithFile(t, "0 1\n", "--window", value, "windows")
173				if got.code != 2 {
174					t.Fatalf("window %q: code = %d, stderr = %q", value, got.code, got.stderr)
175				}
176				if got.stdout != "" {
177					t.Fatalf("stdout = %q", got.stdout)
178				}
179			})
180		}
181	}
182	
183	func TestRunMissingFileAndDirectory(t *testing.T) {
184		dir := t.TempDir()
185		missing := filepath.Join(dir, "does-not-exist")
186		if got := runArgs(t, "--file", missing, "--window", "1s", "windows"); got.code != 3 {
187			t.Fatalf("missing file: code = %d, stderr = %q", got.code, got.stderr)
188		}
189		if got := runArgs(t, "--file", dir, "--window", "1s", "windows"); got.code != 3 {
190			t.Fatalf("directory: code = %d, stderr = %q", got.code, got.stderr)
191		}
192	}
193	
194	func TestRunContentErrors(t *testing.T) {
195		cases := []struct {
196			name    string
197			content string
198			line    string
199		}{
200			{"empty file", "", "0"},
201			{"only blank lines", "\n  \n\t\n", "0"},
202			{"bad timestamp", "0 1\nx 2\n", "2"},
203			{"timestamp out of range", "9223372036854775808 1\n", "1"},
204			{"bad value", "0 not-a-number\n", "1"},
205			{"non-finite NaN", "0 NaN\n", "1"},
206			{"non-finite infinity", "0 +Inf\n", "1"},
207			{"one field", "0\n", "1"},
208			{"three fields", "0 1 2\n", "1"},
209			{"out of order", "100 1\n50 2\n", "2"},
210			{"equal timestamp accepted", "100 1\n100 2\n", "ok"},
211		}
212		for _, tc := range cases {
213			t.Run(tc.name, func(t *testing.T) {
214				got := runWithFile(t, tc.content, "--window", "1ns", "windows")
215				if tc.line == "ok" {
216					if got.code != 0 {
217						t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
218					}
219					return
220				}
221				if got.code != 4 {
222					t.Fatalf("code = %d, want 4, stderr = %q", got.code, got.stderr)
223				}
224				if got.stdout != "" {
225					t.Fatalf("no output on content error, got %q", got.stdout)
226				}
227				if !strings.HasPrefix(got.stderr, "rollupctl: ") {
228					t.Fatalf("stderr = %q", got.stderr)
229				}
230				if !strings.Contains(got.stderr, ":"+tc.line+":") {
231					t.Fatalf("stderr = %q, want line %s", got.stderr, tc.line)
232				}
233			})
234		}
235	}
236	
237	func TestRunLongLine(t *testing.T) {
238		t.Run("exactly 1024 accepted", func(t *testing.T) {
239			// "0 " plus 1016 digits plus "e-1000" is 1024 bytes and parses to
240			// a finite value.
241			content := "0 " + strings.Repeat("9", 1016) + "e-1000\n"
242			if len(content) != 1025 { // 1024 bytes plus the newline
243				t.Fatalf("test setup: line is %d bytes", len(content)-1)
244			}
245			got := runWithFile(t, content, "--window", "1ns", "windows")
246			if got.code != 0 {
247				t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
248			}
249		})
250		t.Run("1025 rejected", func(t *testing.T) {
251			content := "0 " + strings.Repeat("9", 1017) + "e-1000\n"
252			got := runWithFile(t, content, "--window", "1ns", "windows")
253			if got.code != 4 {
254				t.Fatalf("code = %d, want 4, stderr = %q", got.code, got.stderr)
