1	package main
2	
3	import (
4		"bytes"
5		"fmt"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	
11		"github.com/Hulalalalalalalalalalala/metric-rollup/rollup"
12	)
13	
14	// runWithFiles writes each named content to its own file and runs the
15	// command with the given arguments, replacing every "<name>" placeholder
16	// with the file's path.
17	func runWithFiles(t *testing.T, contents map[string]string, args ...string) runResult {
18		t.Helper()
19		dir := t.TempDir()
20		full := make([]string, 0, len(args))
21		for _, a := range args {
22			if content, ok := contents[a]; ok {
23				path := filepath.Join(dir, a)
24				if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
25					t.Fatal(err)
26				}
27				a = path
28			}
29			full = append(full, a)
30		}
31		return runArgs(t, full...)
32	}
33	
34	func TestRangeSelectsHalfOpenInterval(t *testing.T) {
35		content := strings.Join([]string{
36			"0 1",
37			"500000000 2",
38			"1000000000 -3",
39			"1500000000 4",
40			"2000000000 5",
41		}, "\n") + "\n"
42		files := map[string]string{"samples.txt": content}
43	
44		// [1s, 2s) keeps the windows starting at 1s; the window starting
45		// exactly at --to is excluded.
46		got := runWithFiles(t, files, "--file", "samples.txt", "--window", "1s",
47			"range", "--from", "1000000000", "--to", "2000000000")
48		if got.code != 0 {
49			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
50		}
51		if want := "1000000000 2 1 -3 4\n"; got.stdout != want {
52			t.Fatalf("stdout = %q, want %q", got.stdout, want)
53		}
54	
55		// A start inside a window selects the whole window containing it.
56		got = runWithFiles(t, files, "--file", "samples.txt", "--window", "1s",
57			"range", "--from", "1200000000", "--to", "1500000000")
58		if got.code != 0 {
59			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
60		}
61		if want := "1000000000 2 1 -3 4\n"; got.stdout != want {
62			t.Fatalf("stdout = %q, want %q", got.stdout, want)
63		}
64	}
65	
66	func TestRangeEmptyResultsAreNotErrors(t *testing.T) {
67		files := map[string]string{"samples.txt": "0 1\n1000000000 2\n"}
68		for name, endpoints := range map[string][2]string{
69			"from equals to":   {"1000000000", "1000000000"},
70			"from after to":    {"2000000000", "1000000000"},
71			"no window inside": {"2000000000", "3000000000"},
72			"before first":     {"-3000000000", "-2000000000"},
73		} {
74			t.Run(name, func(t *testing.T) {
75				got := runWithFiles(t, files, "--file", "samples.txt", "--window", "1s",
76					"range", "--from", endpoints[0], "--to", endpoints[1])
77				if got.code != 0 {
78					t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
79				}
80				if got.stdout != "" {
81					t.Fatalf("stdout = %q, want empty", got.stdout)
82				}
83			})
84		}
85	}
86	
87	func TestRangeCoversManyWindowsInBatches(t *testing.T) {
88		// More windows than one cursor batch, so iteration must advance.
89		var lines []string
90		for i := 0; i < 3000; i++ {
91			lines = append(lines, fmt.Sprintf("%d %d", i*1000000, i))
92		}
93		files := map[string]string{"samples.txt": strings.Join(lines, "\n") + "\n"}
94		got := runWithFiles(t, files, "--file", "samples.txt", "--window", "1ms",
95			"range", "--from", "0", "--to", "3000000000")
96		if got.code != 0 {
97			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
98		}
99		out := strings.Split(strings.TrimRight(got.stdout, "\n"), "\n")
100		if len(out) != 3000 {
101			t.Fatalf("got %d lines, want 3000", len(out))
102		}
103		if out[0] != "0 1 0 0 0" || out[2999] != "2999000000 1 2999 2999 2999" {
104			t.Fatalf("first = %q, last = %q", out[0], out[2999])
105		}
106	}
107	
108	func TestRangeNegativeAndExtremeEndpoints(t *testing.T) {
