// agg holds one window's exact positive and negative totals, apart from
// the Window the roller stores.
type agg struct {
	// pos and neg are the exact sums of the magnitudes of the positive and
	// negative finite samples respectively; zero values contribute to
	// neither. posZero/negZero record whether a positive/negative zero was
	// among the samples, which decides the sign of an exact-zero result.
	pos, neg       magAccum
	posZero, negZero bool
