//
//   - totals that round into the float64 range are their correctly rounded
//     exact value,
//   - a total past the range is +Inf or -Inf by its sign,
//   - an exact zero is negative zero only when every sample was a negative
//     zero, and positive zero otherwise,
//   - positive and negative infinities together yield NaN.
func (a *agg) sum() float64 {
	if a.pos.inf && a.neg.inf {
		return math.NaN()
	}
	if a.pos.inf {
		return math.Inf(1)
	}
	if a.neg.inf {
		return math.Inf(-1)
	}
	pos, posOK := a.pos.float()
	neg, negOK := a.neg.float()
