// magAccum is an exact sum of nonnegative magnitudes, each an integer
// mantissa times a power of two.
type magAccum struct {
	// mant[scale] is the integer coefficient at 2^scale. A single bucket
	// would suffice, but keeping additions by scale leaves every add with
	// a small integer and pushes the one big-integer rollup into float.
	mant map[int]*big.Int
	inf  bool
