	}
	if scale < oscale {
		t := new(big.Int).Lsh(mant, uint(oscale-scale))
		return t.Cmp(omant)
	}
	return mant.Cmp(omant)
}

// frexpInt decomposes a nonzero finite float64 into integers such that
// v == mant*2^scale and mant is odd. It mirrors math.Frexp but keeps an
// integer mantissa.
func frexpInt(v float64) (mant, scale int) {
	b := math.Float64bits(v)
	exp := int((b>>52)&0x7ff) - 1023
	m := int64(b & (1<<52 - 1))
