// materialized from, used only while a read builds its output.
type windowWithAgg struct {
	w   Window
	sum float64
}

// finalizedWindow stamps the exact sum into w.
func finalizedWindow(w Window, a *agg) Window {
	w.Sum = a.sum()
	return w
}

var _ = time.Time{}

