// Exact, order-independent accumulation of the samples of one window.
//
// A float64 sum changes with the order of addition because every add
// rounds; to make a window's sum a function of its sample set alone, the
// positive and negative magnitudes of a window's finite samples are kept
// exactly as integer totals at powers of two, and rounded to float64 once
// when the window is read. Each finite float64 is mant*2^scale with an
// integer mant, so the totals stay exact at any sample count and through
// any merge, and the single final rounding is the same no matter the
// order samples or whole windows arrived in.

package rollup

import (
	"math"
	"math/big"
)

// agg holds one window's exact totals, apart from the Window the roller
// stores. It is the mutable counterpart that Add and Merge update; reads
// finalize it into the Sum/Min/Max fields of a Window copy.
type agg struct {
	// pos and neg are the exact sums of the magnitudes of the positive
	// and negative finite non-zero samples. posZero/negZero record whether
	// a positive/negative zero was among the samples, which decides the
	// sign of an exact-zero result and of zero extrema.
	pos, neg         exactMag
	posZero, negZero bool
}

// add folds one finite value into a.
func (a *agg) add(v float64) {
	switch {
	case v > 0:
		mant, scale := frexpInt(v)
		a.pos.add(mant, scale)
	case v < 0:
		mant, scale := frexpInt(v)
		a.neg.add(mant, scale)
	case math.Signbit(v):
		a.negZero = true
	default:
		a.posZero = true
	}
}

// merge folds every sample recorded in b into a.
func (a *agg) merge(b *agg) {
	if b == nil {
		return
	}
	a.pos.merge(&b.pos)
	a.neg.merge(&b.neg)
	a.posZero = a.posZero || b.posZero
	a.negZero = a.negZero || b.negZero
}

// clone returns an independent copy.
func (a *agg) clone() *agg {
	if a == nil {
		return nil
	}
	c := &agg{posZero: a.posZero, negZero: a.negZero}
	c.pos = a.pos.clone()
	c.neg = a.neg.clone()
	return c
}

// seed builds an agg from an already-aggregated Window, used when a window
// entered the roller through a test seam without one. A finite sum is
// imported as a single term; an imported infinity keeps its sticky sign
// and an imported NaN counts as both signs, matching how finalize would
// have read it.
func seedAgg(w Window) *agg {
	a := &agg{}
	switch {
	case math.IsNaN(w.Sum):
		a.pos.inf, a.neg.inf = true, true
	case math.IsInf(w.Sum, 1):
		a.pos.inf = true
	case math.IsInf(w.Sum, -1):
		a.neg.inf = true
	case w.Sum != 0:
		mant, scale := frexpInt(w.Sum)
		if w.Sum > 0 {
			a.pos.add(mant, scale)
		} else {
			a.neg.add(mant, scale)
		}
	}
	if w.Min == 0 && math.Signbit(w.Min) {
		a.negZero = true
	}
	if w.Max == 0 && !math.Signbit(w.Max) {
		a.posZero = true
	}
	return a
}

// finalize stamps the exact sum and the fixed zero signs of the extrema
// into a copy of w.
func finalize(w Window, a *agg) Window {
	if a != nil {
		w.Sum = a.sum()
		if w.Min == 0 && a.negZero {
			w.Min = math.Copysign(0, -1)
		}
		if w.Max == 0 {
			if a.posZero {
				w.Max = 0
			} else if a.negZero {
				w.Max = math.Copysign(0, -1)
			}
		}
	}
	return w
}

// sum returns the window total under the fixed conventions:
//
//   - a positive or negative total past the float64 range is +Inf or -Inf,
//   - both sign totals out of range give NaN,
//   - an exact zero is negative zero only when every sample was a negative
//     zero, and positive zero otherwise,
//   - everything else is the exact difference of the two totals rounded
//     once to nearest, ties to even.
func (a *agg) sum() float64 {
	posInf := a.pos.overflows()
	negInf := a.neg.overflows()
	switch {
	case posInf && negInf:
		return math.NaN()
	case posInf:
		return math.Inf(1)
	case negInf:
		return math.Inf(-1)
	case a.pos.total == nil && a.neg.total == nil:
		return a.zero()
	}
	// Combine the two exact integer totals at the smaller scale, so
	// cancellation loses nothing before the single rounding.
	d := new(big.Int)
	scale := a.pos.scale
	if a.neg.total != nil && (a.pos.total == nil || a.neg.scale < scale) {
		scale = a.neg.scale
	}
	if a.pos.total != nil {
		d.Add(d, shifted(a.pos.total, a.pos.scale, scale))
	}
	if a.neg.total != nil {
		d.Sub(d, shifted(a.neg.total, a.neg.scale, scale))
	}
	switch d.Sign() {
	case 0:
		return a.zero()
	case -1:
		return -roundMagnitude(new(big.Int).Neg(d), scale)
	default:
		return roundMagnitude(d, scale)
	}
}

// zero returns the signed zero for a window whose non-zero samples total
// exactly zero: negative zero only if all samples were negative zeros.
func (a *agg) zero() float64 {
	if a.negZero && !a.posZero {
		return math.Copysign(0, -1)
	}
	return 0
}

// shifted returns t*2^(from-scale), which is an exact left shift because
// callers pass scale <= from.
func shifted(t *big.Int, from, scale int) *big.Int {
	if from == scale {
		return t
	}
	return new(big.Int).Lsh(t, uint(from-scale))
}

// exactMag is an exact sum of nonnegative magnitudes, each an integer
// mantissa times a power of two: total is mantissa coefficients summed in
// units of 2^scale, with scale the smallest term scale seen so far.
type exactMag struct {
	total *big.Int
	scale int
	// inf marks a magnitude imported already infinite; filed samples are
	// always finite, so it is set only by seedAgg.
	inf bool
}

// add adds mant*2^scale with mant > 0.
func (m *exactMag) add(mant, scale int) {
	if m.total == nil {
		m.total = big.NewInt(int64(mant))
		m.scale = scale
		return
	}
	if scale < m.scale {
		m.total.Lsh(m.total, uint(m.scale-scale))
		m.scale = scale
	}
	t := big.NewInt(int64(mant))
	if scale > m.scale {
		t.Lsh(t, uint(scale-m.scale))
	}
	m.total.Add(m.total, t)
}

// merge adds every term of o.
func (m *exactMag) merge(o *exactMag) {
	if o.inf {
		m.inf = true
	}
	if o.total == nil {
		return
	}
	if m.total == nil {
		m.total = new(big.Int).Set(o.total)
		m.scale = o.scale
		return
	}
	if o.scale < m.scale {
		m.total.Lsh(m.total, uint(m.scale-o.scale))
		m.scale = o.scale
	}
	m.total.Add(m.total, shifted(o.total, o.scale, m.scale))
}

// clone returns an independent copy.
func (m exactMag) clone() exactMag {
	if m.total == nil {
		return exactMag{inf: m.inf}
	}
	return exactMag{total: new(big.Int).Set(m.total), scale: m.scale, inf: m.inf}
}

// overflows reports whether the magnitude rounds past the largest finite
// float64. The sticky imported infinity counts; otherwise the exact
// magnitude is rounded once purely to test its range.
func (m *exactMag) overflows() bool {
	if m.inf {
		return true
	}
	if m.total == nil {
		return false
	}
	return math.IsInf(roundMagnitude(m.total, m.scale), 1)
}

// roundMagnitude rounds the positive integer magnitude t*2^scale to the
// nearest float64, ties to even. A magnitude at or above the overflow
// threshold returns +Inf; one below the smallest subnormal returns 0.
func roundMagnitude(t *big.Int, scale int) float64 {
	bl := t.BitLen() - 1
	lead := bl + scale // exponent of t's leading bit
	if lead >= 1024 {
		return math.Inf(1)
	}
	// Lowest bit of the retained significand: 53-bit precision in the
	// normal range, down to the subnormal grid at exponent -1074.
	grid := lead - 52
	if grid < -1074 {
		grid = -1074
	}
	drop := grid - scale
	var q *big.Int
	exp := scale
	if drop <= 0 {
		q = t
	} else {
		q = roundHalfEven(t, uint(drop))
		exp = grid
	}
	if q.Sign() == 0 {
		return 0
	}
	// A carry out of the significand at the top exponent reaches 2^1024,
	// which rounds to infinity.
	if q.BitLen() == 54 && lead == 1023 {
		return math.Inf(1)
	}
	return math.Ldexp(float64(q.Int64()), exp)
}

// roundHalfEven returns t rounded to a multiple of 2^s, ties to even.
func roundHalfEven(t *big.Int, s uint) *big.Int {
	mask := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), s), big.NewInt(1))
	low := new(big.Int).And(t, mask)
	q := new(big.Int).Rsh(t, s)
	half := new(big.Int).Lsh(big.NewInt(1), s-1)
	switch low.Cmp(half) {
	case 1:
		q.Add(q, big.NewInt(1))
	case 0:
		if q.Bit(0) != 0 {
			q.Add(q, big.NewInt(1))
		}
	}
	return q
}

// frexpInt decomposes a non-zero finite float64 into integers with
// v == mant*2^scale. It mirrors math.Frexp with an integer mantissa; the
// mantissa need not be odd because the totals combine exactly regardless.
func frexpInt(v float64) (mant, scale int) {
	b := math.Float64bits(v)
	m := int64(b & (1<<52 - 1))
	if b&(1<<63-1) == 0 {
		// Defensive: callers pass non-zero values.
	}
	if (b>>52)&0x7ff == 0 {
		// Subnormal: value is m*2^-1074 with m in [1, 2^52).
		return int(m), -1074
	}
	return int(m | 1<<52), int((b>>52)&0x7ff) - 1023 - 52
}

