// mergeViewLocked returns the sorted union of the two sides by window
// start, pairing windows that share a start without copying either side's
// accumulators. A shared start yields one provisional window (counts and
// extrema combined) with a nil accumulator: callers finalize such entries
// with finalizePair, which merges the two live totals only at read time.
// The caller must hold the lock that guards every accumulator involved.
func mergeViewLocked(a []Window, aa []*agg, b []Window, bb []*agg) ([]Window, []*agg) {
	ws := make([]Window, 0, len(a)+len(b))
	as := make([]*agg, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		switch {
		case a[i].Start.Before(b[j].Start):
			ws = append(ws, a[i])
			as = append(as, aggAt(aa, i, a[i]))
			i++
		case b[j].Start.Before(a[i].Start):
			ws = append(ws, b[j])
			as = append(as, aggAt(bb, j, b[j]))
			j++
		default:
			w := a[i]
			w.Count = satAdd(w.Count, b[j].Count)
			w.Sum += b[j].Sum
			if b[j].Min < w.Min {
				w.Min = b[j].Min
			}
			if b[j].Max > w.Max {
				w.Max = b[j].Max
			}
			// Encode the pair as two accumulators in one slot via a
			// throwaway pairAgg; built lazily only for overlapping starts,
			// which are rare on the hot read path.
			x, y := aggAt(aa, i, a[i]), aggAt(bb, j, b[j])
			ws = append(ws, w)
			as = append(as, pairAccum{x, y}.agg())
			i++
			j++
		}
	}
	for ; i < len(a); i++ {
		ws = append(ws, a[i])
		as = append(as, aggAt(aa, i, a[i]))
	}
	for ; j < len(b); j++ {
		ws = append(ws, b[j])
		as = append(as, aggAt(bb, j, b[j]))
	}
	return ws, as
}

