1	// Exact, order-independent accumulation of the samples of one window.
2	//
3	// A float64 sum changes with the order of addition because every add
4	// rounds; to make a window's sum a function of its sample set alone, the
5	// positive and negative magnitudes of a window's finite samples are kept
6	// exactly as integer totals at powers of two, and rounded to float64 once
7	// when the window is read. Each finite float64 is mant*2^scale with an
8	// integer mant, so the totals stay exact at any sample count and through
9	// any merge, and the single final rounding is the same no matter the
10	// order samples or whole windows arrived in.
11	
12	package rollup
13	
14	import (
15		"math"
16		"math/big"
17		"sync/atomic"
18	)
19	
20	// uncachedSentinel marks an accumulator whose finalized sum is stale. It
21	// is a quiet NaN bit pattern distinct from the canonical NaN a sum can
22	// take (math.NaN has payload bit 1), so it is never mistaken for a
23	// cached result.
24	const uncachedSentinel = 0x7ff8000000000002
25	
26	// agg holds one window's exact totals, apart from the Window the roller
27	// stores. It is the mutable counterpart that Add and Merge update; reads
28	// finalize it into the Sum/Min/Max fields of a Window copy.
29	//
30	// cache holds the Float64bits of the finalized sum, recomputed only after
31	// a write. Reads run under the roller's read lock and may overlap, so the
32	// cache is updated atomically; a missed cache computes the same value
33	// either way.
34	type agg struct {
35		// pos and neg are the exact sums of the magnitudes of the positive
36		// and negative finite non-zero samples. posZero/negZero record whether
37		// a positive/negative zero was among the samples, which decides the
38		// sign of an exact-zero result and of zero extrema.
39		pos, neg         exactMag
40		posZero, negZero bool
41		cache            atomic.Uint64
42	}
43	
44	// newAgg returns an accumulator with no cached sum.
45	func newAgg() *agg {
46		a := &agg{}
47		a.cache.Store(uncachedSentinel)
48		return a
49	}
50	
51	// invalidate drops the cached finalized sum after a change.
52	func (a *agg) invalidate() {
53		a.cache.Store(uncachedSentinel)
54	}
55	
56	// add folds one finite value into a.
57	func (a *agg) add(v float64) {
58		switch {
59		case v > 0:
60			mant, scale := frexpInt(v)
61			a.pos.add(mant, scale)
62		case v < 0:
63			mant, scale := frexpInt(v)
64			a.neg.add(mant, scale)
65		case math.Signbit(v):
66			a.negZero = true
67		default:
68			a.posZero = true
69		}
70		a.invalidate()
71	}
72	
73	// merge folds every sample recorded in b into a.
74	func (a *agg) merge(b *agg) {
75		if b == nil {
76			return
77		}
78		a.pos.merge(&b.pos)
79		a.neg.merge(&b.neg)
80		a.posZero = a.posZero || b.posZero
81		a.negZero = a.negZero || b.negZero
82		a.invalidate()
83	}
84	
85	// clone returns an independent copy.
86	func (a *agg) clone() *agg {
87		if a == nil {
88			return nil
89		}
90		c := newAgg()
91		c.pos = a.pos.clone()
92		c.neg = a.neg.clone()
93		c.posZero = a.posZero
94		c.negZero = a.negZero
95		return c
96	}
97	
98	// seedAgg builds an agg from an already-aggregated Window, used when a
99	// window entered the roller through a test seam without one. A finite
100	// sum is imported as a single term; an imported infinity keeps its sticky
101	// sign and an imported NaN counts as both signs, matching how finalize
102	// would have read it. The extrema keep their stored signs, which is
103	// exact for the finite, non-negative-zero values the seams use.
104	func seedAgg(w Window) *agg {
105		a := newAgg()
106		switch {
107		case math.IsNaN(w.Sum):
108			a.pos.inf, a.neg.inf = true, true
109		case math.IsInf(w.Sum, 1):
110			a.pos.inf = true
111		case math.IsInf(w.Sum, -1):
112			a.neg.inf = true
113		case w.Sum != 0:
114			mant, scale := frexpInt(w.Sum)
115			if w.Sum > 0 {
116				a.pos.add(mant, scale)
117			} else {
118				a.neg.add(mant, scale)
119			}
120		}
121		return a
122	}
123	
124	// finalize stamps the exact sum and the fixed zero signs of the extrema
125	// into a copy of w.
126	func finalize(w Window, a *agg) Window {
127		if a != nil {
128			w.Sum = a.sum()
129			if w.Min == 0 && a.negZero {
130				w.Min = math.Copysign(0, -1)
131			}
132			if w.Max == 0 {
133				if a.posZero {
134					w.Max = 0
135				} else if a.negZero {
136					w.Max = math.Copysign(0, -1)
137				}
138			}
139		}
140		return w
141	}
142	
143	// sum returns the window total under the fixed conventions:
144	//
145	//   - a positive or negative total past the float64 range is +Inf or -Inf,
146	//   - both sign totals out of range give NaN,
147	//   - an exact zero is negative zero only when every sample was a negative
148	//     zero, and positive zero otherwise,
149	//   - everything else is the exact difference of the two totals rounded
150	//     once to nearest, ties to even.
151	func (a *agg) sum() float64 {
152		if c := a.cache.Load(); c != uncachedSentinel {
153			return math.Float64frombits(c)
154		}
155		v := a.compute()
156		a.cache.Store(math.Float64bits(v))
157		return v
158	}
159	
160	// compute applies the fixed conventions without touching the cache.
161	func (a *agg) compute() float64 {
162		posInf := a.pos.overflows()
163		negInf := a.neg.overflows()
164		switch {
165		case posInf && negInf:
166			return math.NaN()
167		case posInf:
168			return math.Inf(1)
169		case negInf:
170			return math.Inf(-1)
171		case a.pos.total == nil && a.neg.total == nil:
172			return a.zero()
173		}
174		// Combine the two exact integer totals at the smaller scale, so
175		// cancellation loses nothing before the single rounding.
176		d := new(big.Int)
177		scale := a.pos.scale
178		if a.neg.total != nil && (a.pos.total == nil || a.neg.scale < scale) {
179			scale = a.neg.scale
180		}
181		if a.pos.total != nil {
182			d.Add(d, shifted(a.pos.total, a.pos.scale, scale))
183		}
184		if a.neg.total != nil {
