// addBig folds one term whose coefficient is c, optionally taking
// ownership of c.
func (m *exactMag) addBig(c *big.Int, scale int, ownC bool) {
	if scale < m.scale {
		m.writable().Lsh(m.bigc, uint(m.scale-scale))
		m.scale = scale
	}
