	if scale > m.scale {
		if ownC {
			t.Lsh(t, uint(scale-m.scale))
		} else {
			t = new(big.Int).Lsh(c, uint(scale-m.scale))
		}
	} else if !ownC {
		t = new(big.Int).Set(c)
	}
	m.writable().Add(m.bigc, t)
}

