// by window start, combining the statistics of windows that share a
// start: counts and sums add, minimums take the smaller, maximums take
// the larger. The result is always fresh: every returned accumulator is an
// independent copy folded from both sides, so neither input is mutated
// and the destination never shares an accumulator with another roller.
func mergeWindows(a []Window, aa []*agg, b []Window, bb []*agg) ([]Window, []*agg) {
	merged := make([]Window, 0, len(a)+len(b))
	mergedAgg := make([]*agg, 0, len(a)+len(b))
	put := func(w Window, x, y *agg) {
		ag := newAgg()
		ag.merge(x)
		ag.merge(y)
		merged = append(merged, w)
		mergedAgg = append(mergedAgg, ag)
	}
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		switch {
		case a[i].Start.Before(b[j].Start):
			put(a[i], aggAt(aa, i, a[i]), nil)
			i++
