// snapshotLocked returns every window in time order paired with its
// accumulator, merged from buckets and the backfill map. The caller must
// hold mu. The accumulators are the roller's live ones and are only read,
// never copied or mutated, so the result is valid only while the lock is
// held: reads finalize the windows in place, and Merge passes them to
// mergeWindows, which folds the accumulators into fresh copies.
//
// buckets and the backfill map are disjoint in window starts by
// construction, so their union is a plain interleave: no statistics ever
// combine here.
func (r *Roller) snapshotLocked() ([]Window, []*agg) {
	if len(r.back) == 0 {
		ws := make([]Window, len(r.buckets))
		copy(ws, r.buckets)
		return ws, r.sums
	}
	bw, ba := r.sortedBackLocked()
	ws := make([]Window, 0, len(r.buckets)+len(bw))
	as := make([]*agg, 0, len(r.buckets)+len(bw))
	i, j := 0, 0
	for i < len(r.buckets) && j < len(bw) {
		if bw[j].Start.Before(r.buckets[i].Start) {
			ws = append(ws, bw[j])
			as = append(as, ba[j])
			j++
		} else {
			ws = append(ws, r.buckets[i])
			as = append(as, aggAt(r.sums, i, r.buckets[i]))
			i++
		}
	}
	for ; i < len(r.buckets); i++ {
		ws = append(ws, r.buckets[i])
		as = append(as, aggAt(r.sums, i, r.buckets[i]))
	}
	ws = append(ws, bw[j:]...)
	as = append(as, ba[j:]...)
	return ws, as
}

