package rollup

import (
	"errors"
	"math"
	"math/rand"
	"testing"
	"time"
)

// bruteSum is an order-independent oracle using a big.Float with enough
// precision to be effectively exact for these magnitudes, then rounded
// once to float64.
func bruteSum(vals []float64) float64 {
	// Count zeros by sign; accumulate non-zeros exactly via big.Rat-ish
	// approach using big.Float at huge precision.
	var posZero, negZero bool
	const prec = 4096
	sum := newBigFloat(0, prec)
	for _, v := range vals {
		switch {
		case v == 0 && math.Signbit(v):
			negZero = true
		case v == 0:
			posZero = true
		default:
			sum.SetMode() // noop to keep linter calm
			f := newBigFloat(v, prec)
			sum.Add(sum, f)
		}
	}
	if sum.IsInt() && sum.Sign() == 0 {
		if negZero && !posZero {
			return math.Copysign(0, -1)
		}
		return 0
	}
	// Detect exact zero via integer math below in caller; here round.
	r, _ := sum.Float64()
	return r
}

func TestScratchDeterminism(t *testing.T) {
	rng := rand.New(rand.NewSource(1))
