func TestScratchInfinity(t *testing.T) {
	r := New(time.Minute)
	if err := r.Add(time.Unix(0, 0), math.MaxFloat64); err != nil {
		t.Fatal(err)
	}
	if err := r.Add(time.Unix(0, 0), math.MaxFloat64); err != nil {
		t.Fatal(err)
	}
	w, _ := r.Window(time.Unix(0, 0))
	if !math.IsInf(w.Sum, 1) {
		t.Fatalf("want +Inf, got %v", w.Sum)
	}
	// Min of positive is positive.
	if w.Min <= 0 || w.Max <= 0 {
		t.Fatalf("extreme: %v %v", w.Min, w.Max)
	}

	r2 := New(time.Minute)
	r2.Add(time.Unix(0, 0), -math.MaxFloat64)
	r2.Add(time.Unix(0, 0), -math.MaxFloat64)
