func TestScratchNonFiniteRejected(t *testing.T) {
	for _, v := range []float64{math.NaN(), math.Inf(1), math.Inf(-1)} {
		r := New(time.Minute)
		if err := r.Add(time.Unix(0, 0), v); !errors.Is(err, ErrNonFinite) {
			t.Fatalf("Add(%v) = %v, want ErrNonFinite", v, err)
		}
		if got := r.Windows(); len(got) != 0 {
			t.Fatalf("rejected add changed state: %+v", got)
		}
		// Marker must not move: accept an earlier sample afterwards.
		if err := r.Add(time.Unix(100, 0), 1); err != nil {
			t.Fatal(err)
		}
		if err := r.Add(time.Unix(0, 0), 1); !errors.Is(err, ErrOutOfOrder) {
			t.Fatalf("want ErrOutOfOrder, got %v", err)
		}

		// Batch atomicity.
		r2 := New(time.Minute)
		r2.Add(time.Unix(0, 0), 1)
		batch := []Sample{
			{At: time.Unix(100, 0), Value: 2},
			{At: time.Unix(200, 0), Value: v},
			{At: time.Unix(300, 0), Value: 3},
		}
		if err := r2.AddBatch(batch); !errors.Is(err, ErrNonFinite) {
			t.Fatalf("AddBatch(%v) = %v, want ErrNonFinite", v, err)
		}
		if got := r2.Windows(); len(got) != 1 {
			t.Fatalf("rejected batch changed state: %+v", got)
		}
		if err := r2.Add(time.Unix(50, 0), 1); !errors.Is(err, ErrOutOfOrder) {
			t.Fatalf("marker moved after rejected batch: %v", err)
		}
	}
}

func TestScratchBatchMergeOrder(t *testing.T) {
	// Build same sample set via: adds; batch; two rollers merged.
	vals := []float64{1e16, 1, -1, 1e16, 0.1, -0.1, 123456.789, 2, -2, 5}
	var want float64
	a := New(time.Minute)
	for _, v := range vals {
		want += v
		a.Add(time.Unix(0, 0), v)
	}
	wa, _ := a.Window(time.Unix(0, 0))

	// Via two halves merged.
	b := New(time.Minute)
	c := New(time.Minute)
	for i, v := range vals {
		if i%2 == 0 {
			b.Add(time.Unix(0, 0), v)
		} else {
			c.Add(time.Unix(0, 0), v)
		}
	}
	b.Merge(c)
	wb, _ := b.Window(time.Unix(0, 0))

	// Via one shuffled batch.
	d := New(time.Minute)
	d.AddBatch(toSamples(vals[::-1]))
	wd, _ := d.Window(time.Unix(0, 0))

	if bits(wa.Sum) != bits(wb.Sum) || bits(wb.Sum) != bits(wd.Sum) {
		t.Fatalf("paths differ: adds=%v merge=%v batch=%v (naive=%v)", wa.Sum, wb.Sum, wd.Sum, want)
	}
	t.Logf("deterministic sum = %v (naive left-to-right = %v)", wa.Sum, want)
}

func toSamples(vals []float64) []Sample {
	s := make([]Sample, len(vals))
	for i, v := range vals {
		s[i] = Sample{At: time.Unix(0, 0), Value: v}
	}
	return s
}

