// exactSumFloat is an independent oracle: it sums the exact rational
// values of the inputs with a big.Float at ample precision, then rounds
// once to float64. Only for sums that stay finite and away from the
// overflow/underflow extremes, where the oracle and the roller must agree
// to the bit.
func exactSumFloat(vals []float64) (float64, bool) {
	const prec = 20000
	sum := new(big.Float).SetPrec(prec)
	tmp := new(big.Float).SetPrec(prec)
	for _, v := range vals {
		if v == 0 {
			continue
		}
		tmp.SetFloat64(v)
		sum.Add(sum, tmp)
	}
	if sum.IsInf() {
		return 0, false
	}
	r, acc := sum.Float64()
	if math.IsInf(r, 0) || (r == 0 && acc != big.Exact && sum.Sign() != 0) {
		return 0, false
	}
	return r, true
}

