	rng := rand.New(rand.NewSource(7))
	for trial := 0; trial < 300; trial++ {
		n := 1 + rng.Intn(200)
		vals := make([]float64, n)
		for i := range vals {
			// Keep magnitudes bounded so the exact total stays mid-range.
			vals[i] = (rng.Float64()*2 - 1) * 1e6
			switch rng.Intn(3) {
			case 0:
				vals[i] = float64(rng.Intn(2001) - 1000)
			case 1:
				vals[i] *= 1e8
			}
		}
		want, ok := exactSumFloat(vals)
		if !ok {
			continue
		}
		r := New(time.Minute)
		for _, k := range rng.Perm(n) {
			if err := r.Add(time.Unix(0, 0), vals[k]); err != nil {
				t.Fatal(err)
