// intMagnitudeOverflows reports whether the non-negative int64 magnitude
// coeff*2^scale is at least overflowThreshold, exactly.
func intMagnitudeOverflows(coeff int64, scale int) bool {
	if scale >= 970 {
		// threshold / 2^scale = (2^54-1) >> (scale-970).
		req := int64(1<<54 - 1)
		if d := scale - 970; d > 0 {
			req >>= uint(d)
		}
		return coeff >= req
	}
	// Required coefficient is (2^54-1)*2^(970-scale), larger than any
	// value an int64 coefficient at this scale can reach.
	return false
}

// bigMagnitudeOverflows reports whether bigc*2^scale is at least
// overflowThreshold, exactly.
func bigMagnitudeOverflows(bigc *big.Int, scale int) bool {
	if scale >= 0 {
		// Need bigc >= threshold >> scale (rounding the divisor down makes
		// the test conservative at the boundary, so compare exactly by
		// shifting the other way instead).
		t := new(big.Int).Lsh(bigc, uint(scale))
		return t.Cmp(overflowThreshold) >= 0
	}
	// Need bigc >= threshold << (-scale).
	req := new(big.Int).Lsh(overflowThreshold, uint(-scale))
	return bigc.Cmp(req) >= 0
}

