func TestScratchOverflowBoundary(t *testing.T) {
	// Two values whose exact sum is just under the rounding midpoint stay
	// MaxFloat64; a sum at/above the midpoint rounds to +Inf.
	mx := math.MaxFloat64
	half := mx / 2
	// mx + half = 1.5*mx, well above midpoint -> +Inf.
	r := New(time.Minute)
	r.Add(time.Unix(0, 0), mx)
	r.Add(time.Unix(0, 0), half)
	if w, _ := r.Window(time.Unix(0, 0)); !math.IsInf(w.Sum, 1) {
		t.Fatalf("mx+mx/2 = %v, want +Inf", w.Sum)
	}
	// mx + the smallest ulp-sized increment: the exact sum is mx +
	// 2^971, below the midpoint 2^1024-2^970, so it rounds back to mx.
	r2 := New(time.Minute)
	r2.Add(time.Unix(0, 0), mx)
	r2.Add(time.Unix(0, 0), math.Ldexp(1, 971))
	if w, _ := r2.Window(time.Unix(0, 0)); w.Sum != mx {
		t.Fatalf("mx+2^971 = %v, want MaxFloat64 %v", w.Sum, mx)
	}
	// mx + mx (2*mx) is exactly 2^1024, past max -> +Inf.
	r3 := New(time.Minute)
	r3.Add(time.Unix(0, 0), mx)
	r3.Add(time.Unix(0, 0), mx)
	if w, _ := r3.Window(time.Unix(0, 0)); !math.IsInf(w.Sum, 1) {
		t.Fatalf("2*mx = %v, want +Inf", w.Sum)
	}
}

