func TestScratchInfinity(t *testing.T) {
	r := New(time.Minute)
	r.Add(time.Unix(0, 0), math.MaxFloat64)
	r.Add(time.Unix(0, 0), math.MaxFloat64)
	w, _ := r.Window(time.Unix(0, 0))
	if !math.IsInf(w.Sum, 1) {
		t.Fatalf("want +Inf, got %v", w.Sum)
	}

	r2 := New(time.Minute)
	r2.Add(time.Unix(0, 0), -math.MaxFloat64)
	r2.Add(time.Unix(0, 0), -math.MaxFloat64)
	w2, _ := r2.Window(time.Unix(0, 0))
	if !math.IsInf(w2.Sum, -1) {
		t.Fatalf("want -Inf, got %v", w2.Sum)
	}

	// Opposite infinities -> NaN on merge.
	if err := r.Merge(r2); err != nil {
		t.Fatal(err)
	}
	w3, _ := r.Window(time.Unix(0, 0))
	if !math.IsNaN(w3.Sum) {
		t.Fatalf("want NaN, got %v", w3.Sum)
	}

	// Adding a finite value to an infinite side stays infinite.
	r4 := New(time.Minute)
	r4.Add(time.Unix(0, 0), math.MaxFloat64)
	r4.Add(time.Unix(0, 0), math.MaxFloat64)
	r4.Add(time.Unix(0, 0), -5)
	w4, _ := r4.Window(time.Unix(0, 0))
	if !math.IsInf(w4.Sum, 1) {
		t.Fatalf("want +Inf after finite add, got %v", w4.Sum)
	}
}

func TestScratchNonFiniteRejected(t *testing.T) {
	for _, v := range []float64{math.NaN(), math.Inf(1), math.Inf(-1)} {
		r := New(time.Minute)
		if err := r.Add(time.Unix(0, 0), v); !errors.Is(err, ErrNonFinite) {
			t.Fatalf("Add(%v) = %v, want ErrNonFinite", v, err)
		}
		if got := r.Windows(); len(got) != 0 {
			t.Fatalf("rejected add changed state: %+v", got)
		}
		// Marker must not have moved.
		if err := r.Add(time.Unix(100, 0), 1); err != nil {
			t.Fatal(err)
		}
		if err := r.Add(time.Unix(0, 0), 1); !errors.Is(err, ErrOutOfOrder) {
			t.Fatalf("want ErrOutOfOrder, got %v", err)
		}

		// Batch atomicity: nothing filed, marker unmoved.
		r2 := New(time.Minute)
		r2.Add(time.Unix(0, 0), 1)
		batch := []Sample{
			{At: time.Unix(100, 0), Value: 2},
			{At: time.Unix(200, 0), Value: v},
			{At: time.Unix(300, 0), Value: 3},
		}
		if err := r2.AddBatch(batch); !errors.Is(err, ErrNonFinite) {
			t.Fatalf("AddBatch(%v) = %v, want ErrNonFinite", v, err)
		}
		if got := r2.Windows(); len(got) != 1 {
			t.Fatalf("rejected batch changed state: %+v", got)
		}
		// Marker stayed at t=0: t=0 is still accepted, t=-1 is out of order.
		if err := r2.Add(time.Unix(0, 0), 1); err != nil {
			t.Fatalf("equal instant should be accepted: %v", err)
		}
		if err := r2.Add(time.Unix(-1, 0), 1); !errors.Is(err, ErrOutOfOrder) {
			t.Fatalf("marker moved after rejected batch: %v", err)
		}
	}
}

func TestScratchPathsAgree(t *testing.T) {
	// Same sample set reached via: sequential adds, a shuffled batch, and
	// a merge of two rollers must read bit-identical sums.
	vals := []float64{1e16, 1, -1, 1e16, 0.1, -0.1, 123456.789, 2, -2, 5, 1e-300, -1e-300}

	a := New(time.Minute)
	for _, v := range vals {
		a.Add(time.Unix(0, 0), v)
	}
	wa, _ := a.Window(time.Unix(0, 0))

	b, c := New(time.Minute), New(time.Minute)
	for i, v := range vals {
		if i%2 == 0 {
			b.Add(time.Unix(0, 0), v)
		} else {
			c.Add(time.Unix(0, 0), v)
		}
	}
	b.Merge(c)
	wb, _ := b.Window(time.Unix(0, 0))

	d := New(time.Minute)
	rev := make([]float64, len(vals))
	for i := range vals {
		rev[i] = vals[len(vals)-1-i]
	}
	d.AddBatch(toSamples(rev))
	wd, _ := d.Window(time.Unix(0, 0))

	// And a factor-1 view of the first roller.
	vw := a.Rollup(1).Window(time.Unix(0, 0))

	if fbit(wa.Sum) != fbit(wb.Sum) || fbit(wb.Sum) != fbit(wd.Sum) || fbit(wd.Sum) != fbit(vw.Sum) {
		t.Fatalf("paths differ: adds=%v merge=%v batch=%v view=%v", wa.Sum, wb.Sum, wd.Sum, vw.Sum)
	}
	t.Logf("deterministic sum = %v", wa.Sum)
}

func toSamples(vals []float64) []Sample {
	s := make([]Sample, len(vals))
	for i, v := range vals {
		s[i] = Sample{At: time.Unix(0, 0), Value: v}
	}
	return s
}

